import ast, os
# Walk django package, find ImportFrom nodes with mixed underscore/public names, report ordering
hits = 0
for root, dirs, files in os.walk("django"):
    for fn in files:
        if not fn.endswith(".py"): continue
        path = os.path.join(root, fn)
        try:
            tree = ast.parse(open(path, encoding="utf-8").read())
        except Exception:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and len(node.names) > 1:
                nms = [a.name for a in node.names]
                underscore = [n for n in nms if n.startswith("_")]
                if underscore and any(not n.startswith("_") for n in nms):
                    print(path, node.module, nms)
                    hits += 1
                    if hits > 8: break
    if hits > 8: break
